using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketClassifierService
{
    private readonly MLContext _mlContext;
    private readonly PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
    private readonly EvaluationResponse _evaluationMetrics;
    private readonly string[] _categoryLabels;

    public TicketClassifierService(string dataPath)
    {
        _mlContext = new MLContext(seed: 0);

        var dataView = _mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var pipeline = _mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketData.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features", "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        var model = pipeline.Fit(dataView);

        // Extract category labels from the trained model's key-value mapping
        var transformer = model.LastTransformer.Previous?.Previous as ITransformer;
        _categoryLabels = ExtractCategoryLabels(model, dataView);

        // Evaluate against training data (small dataset — no hold-out split)
        var predictions = model.Transform(dataView);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions, "Label");

        _evaluationMetrics = new EvaluationResponse
        {
            MacroAccuracy = metrics.MacroAccuracy,
            MicroAccuracy = metrics.MicroAccuracy,
            LogLoss = metrics.LogLoss,
            LogLossReduction = metrics.LogLossReduction,
            TrainingSampleCount = (int)_mlContext.Data.CreateEnumerable<TicketData>(dataView, false).Count()
        };

        _predictionEngine = _mlContext.Model.CreatePredictionEngine<TicketData, TicketPrediction>(model);
    }

    public PredictionResponse Predict(TicketRequest request)
    {
        var ticketData = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionEngine.Predict(ticketData);

        var confidenceScores = new Dictionary<string, float>();
        for (int i = 0; i < _categoryLabels.Length && i < prediction.Score.Length; i++)
        {
            confidenceScores[_categoryLabels[i]] = prediction.Score[i];
        }

        return new PredictionResponse
        {
            PredictedCategory = prediction.Category,
            ConfidenceScores = confidenceScores
        };
    }

    public EvaluationResponse GetMetrics() => _evaluationMetrics;

    private string[] ExtractCategoryLabels(ITransformer model, IDataView dataView)
    {
        var transformedData = model.Transform(dataView);
        var schema = transformedData.Schema;

        // The Label column (key type) carries the slot names which are the original category strings
        var labelColumn = schema.GetColumnOrNull("Label");
        if (labelColumn == null)
            return ["Billing", "Technical", "General"];

        var keyType = labelColumn.Value.Type as Microsoft.ML.Data.KeyDataViewType;
        if (keyType == null)
            return ["Billing", "Technical", "General"];

        var slotNames = new Microsoft.ML.Data.VBuffer<ReadOnlyMemory<char>>();
        labelColumn.Value.GetKeyValues(ref slotNames);

        return slotNames.DenseValues().Select(v => v.ToString()).ToArray();
    }
}

